#include <stdio.h>

static unsigned int next_id(void)
{
    static unsigned int next = 1U;
    return next++;
}

int main(void)
{
    unsigned int first = next_id();
    unsigned int second = next_id();
    printf("first=%u second=%u\n", first, second);
    return 0;
}

